local Mm,Nm=F.request(FOe[2524],FOe[2416],vm)
if Mm and Nm then
table.insert(bb.actions,FOe[2721]..Lm..FOe[2722])
F.log(1,FOe[2714],string.format(FOe[2723],V.name(am.id),Lm,ym or 0,U.fmt(wm or 0),V.name(am.id)))
return true
end
