local ao=bb.pasExp
if type(ao)==FOe[2325]and ao.kind==FOe[2524]and not ao.otherDone and not ao.freed and bb.reinc and(bb.reinc.sold or 0)>0 and U.now()-(tonumber(bb.reinc.soldAt)or 0)>20 then
local bo,co=pcall(pb.freeSlot,ao)
