if Vo.Parent then
Xo.last=kn
elseif not Xo.died then
Xo.died=kn
end
end
end
for ap in pairs(gn.ids)do
local bp=bb.casts and tonumber(bb.casts[ap])or 0
if bp>(gn.castN[ap]or 0)then
