table.insert(lq,{pq.born,1})
table.insert(lq,{pq.died or pq.last or pq.born,-1})
end
table.sort(lq,function(qq,rq)
return qq[1]<rq[1]
end)
local sq,tq=0,0
for uq,vq in ipairs(lq)do
