if not Eq then
return{why=FOe[2754]}
end
return{seen=true,nums={stat=Eq,loSeen=Fq,hiSeen=Gq,transformTo=Bq},why=string.format(FOe[2755],Eq,tostring(Fq),tostring(Gq))}
end
return{seen=true,buff=xq,nums={maxSeen=yq.max,steps= #yq.vals,transformTo=Bq},why=string.format(FOe[2756],xq,tostring(yq.max))}
end
if ep.family==FOe[2523]then
local Lq,Mq,Nq={},{},nil
for Oq,Pq in ipairs(cp.steps)do
for Qq,Rq in pairs(Pq.reset or{})do
