function mb.charmApplies(dD)
if not dD then
return false
end
if dD.kind==FOe[2348]and mb.is(dD.level)then
return true
end
return dD.kind==FOe[2796]and tostring(dD.level):find(FOe[2860],1,true)~=nil
end
function mb.charms()
local eD=N.prof()
local fD={}
for gD,hD in pairs((eD and eD.inventory and eD.inventory.unique_items)or{})do
local iD=type(hD)==FOe[2325]and N.Items[hD.item_id]
if type(iD)==FOe[2325]and iD.item_group==FOe[2861]then
local jD={uuid=hD.uuid or gD,id=hD.item_id,tier=tonumber(iD.tier)or 0,rolls={}}
local kD=type(hD._unique_item_data)==FOe[2325]and hD._unique_item_data._unique_charm_data
jD.worn=type(kD)==FOe[2325]and kD._e~=nil
local lD=type(kD)==FOe[2325]and kD._d
for mD,nD in pairs(type(lD)==FOe[2325]and lD or{})do
if type(nD)==FOe[2325]and nD._t then
jD.rolls[tostring(nD._t)]=(jD.rolls[tostring(nD._t)]or 0)+(tonumber(nD._d)or 0)
end
end
table.insert(fD,jD)
end
end
return fD
end
function mb.charmOn()
