function mb.charmWant(LD)
if not O.smartCharm or not mb.charmApplies(LD)then
return nil
end
P.charm=type(P.charm)==FOe[2325]and P.charm or{}
if os.time()-(tonumber(P.charm.failAt)or 0)<1800 then
return nil
end
local MD,ND
for OD,PD in ipairs(mb.charms())do
local QD=mb.charmScore(PD,LD)
if not ND or QD>ND then
MD,ND=PD,QD
end
end
if not MD then
return nil
end
local RD=mb.charmOn()or(F.where==FOe[2406]and P.charm.uuid)or nil
if RD==MD.uuid then
return nil
end
return MD,RD
end
function mb.charmTick(SD)
local TD,UD=mb.charmWant(SD)
