local VD=U.now()
while U.now()-VD<4 and mb.charmOn()~=TD.uuid do
task.wait(0.5)
end
if mb.charmOn()==TD.uuid then
P.charm.uuid,P.charm.at,P.charm.failAt=TD.uuid,os.time(),nil
F.saveSoon()
F.log(1,FOe[2873],string.format(FOe[2874],mb.charmWords(TD),tostring(SD.label),math.floor((tonumber(SD.p)or 0)*100+0.5),(tonumber(SD.p)or 0)>=0.92 and FOe[2865]or FOe[2775]))
else
P.charm.failAt=os.time()
F.saveSoon()
F.log(1,FOe[2873],string.format(FOe[2875],mb.charmWords(TD)))
end
end
function mb.charmSlots()
