local AE=F.gameSaid(wE)
F.log(1,FOe[2873],string.format(FOe[2878],#sE,tostring(AE or yE or FOe[2879])))
F.backoff(FOe[2876],1800)
return
end
cb.add(string.format(FOe[2880],#sE),#sE,FOe[2881],string.format(FOe[2882],rE-zE,rE,table.concat(tE,FOe[2883])))
end
function mb.weatherStrength(BE)
local CE=mb.fx(BE)
local DE=CE.dmg/CE.cd/CE.hp/CE.speed*(1+(CE.range-1)/2)
for EE,FE in pairs(CE.kinds)do
DE=DE*(1+bb.rogueShare(EE)*FE)
end
if CE.ice>0 then
local GE=bb.rogueShare(FOe[2476])
DE=DE*(GE+(1-GE)/(1-CE.ice+CE.ice/gb.modFactor(FOe[2884])))
end
if CE.fly>0 then
DE=DE*(1-CE.fly*0.5)
end
if CE.noCC then
DE=DE*0.95
end
if CE.shroud then
DE=DE*0.9
end
if CE.zap then
DE=DE*0.85
end
return DE/mb.weatherK(BE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(HE)
local IE=HE and type(P.hunt)==FOe[2325]and type(P.hunt.wk)==FOe[2325]and P.hunt.wk[tostring(HE)]or nil
return type(IE)==FOe[2325]and tonumber(IE.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(FOe[1223]):GetPlayers()>1 then
return
end
local JE=bb.huntWeather or mb.weatherNow()
local KE,LE=bb.pred,bb.calRun
if not JE or type(KE)~=FOe[2325]or type(LE)~=FOe[2325]then
return
end
local function ME(NE,OE)
return type(NE)==FOe[2325]and tonumber(NE[OE]or NE[tostring(OE)])or nil
end
local PE={}
for QE=2,bb.wave()do
local RE,SE=ME(LE.alive,QE),ME(KE.aliveAt,QE)
if RE and SE and RE>0 and SE>0 then
table.insert(PE,RE/SE)
end
end
if#PE<3 then
return
end
table.sort(PE)
local TE=PE[math.ceil(#PE/2)]
P.hunt.wk=type(P.hunt.wk)==FOe[2325]and P.hunt.wk or{}
local UE=P.hunt.wk[tostring(JE)]
local VE=math.min(mb.WEATHER_K_RUNS-1,type(UE)==FOe[2325]and tonumber(UE.n)or 0)
local WE=mb.weatherK(JE)
local XE=math.max(1,VE)
local YE=math.exp((XE*math.log(WE)+math.log(WE*TE))/(XE+1))
YE=U.clamp(YE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(JE),old=UE}
P.hunt.wk[tostring(JE)]={k=YE,n=(type(UE)==FOe[2325]and tonumber(UE.n)or 0)+1,at=os.time()}
F.log(1,FOe[2885],string.format(FOe[2886],tostring(JE),TE,tostring(JE),YE,WE,P.hunt.wk[tostring(JE)].n))
end
function mb.cardGems(ZE,_E)
local aF=0
local bF=mb.pearlsFrom(_E+1,50)
for cF,dF in pairs(type(ZE.effects)==FOe[2325]and ZE.effects or{})do
if type(dF)==FOe[2325]then
local eF=tonumber(dF.amount)or 0
if dF.type==FOe[2887]then
aF=aF+math.abs(eF)*bF*O.pearlValue
elseif dF.type==FOe[2888]then
local fF,gF=pcall(W.rewardValue,dF.reward)
if fF then
aF=aF+(tonumber(gF)or 0)
end
elseif dF.type==FOe[2889]then
aF=aF+eF*mb.STARFALL_GEMS
elseif dF.type==FOe[2890]then
aF=aF+eF*100
end
end
end
if ZE.option_type==FOe[2891]then
aF=aF+mb.HARD_GEMS
end
if ZE.weather then
local hF=ZE.weather~=mb.weatherNow()
if hF and ZE.weather==FOe[2826]then
aF=aF+mb.starfallRemnants(50-(tonumber(_E)or 0))*W.remnantGems(FOe[2830])
end
local iF=mb.board()
if hF and iF and ZE.weather~=FOe[2832]and not iF.weathers[ZE.weather]then
aF=aF+(1000+5000*O.pearlValue+50*W.remnantGems(FOe[2830]))/mb.WEATHERS
end
end
return aF
end
