mb.EVENT_DROP={darkness=0.2,darkness_evolved=0.4,aqua=0.2,aqua_evolved=0.4,megumin=0.2,megumin_evolved=0.4,ishmael=0.2,ishmael_evolved=0.4,marco=0.2,marco_evolved=0.4,enel=0.2,enel_evolved=0.4,rudeus=0.2,rudeus_evolved=0.4}
function mb.unitDrop(sF,tF)
