mb.BONUS_BAR,mb.BONUS_SWAPS=1.3,4
function mb.bonusTeam(FF,GF,HF)
if type(FF)~=FOe[2325]or type(GF)~=FOe[2325]or#GF==0 then
return nil
end
local IF,JF=U.now(),N.session()
HF=tonumber(HF)or 12
local KF,LF=pcall(mb.skinPlan)
local MF=KF and type(LF)==FOe[2325]and LF.kinds or{}
local function NF(OF,PF)
local QF,RF=gb.teamFrom(OF,FF.map),0
for SF,TF in ipairs({1,0.92,1.08})do
if gb.run(FF,QF,{hpMul=PF*TF}).won then
RF=RF+1
end
task.wait()
if RF>=2 then
return true
end
if SF==2 and RF==0 then
return false
end
end
return false
end
local UF=(NF(GF,mb.BONUS_BAR)and mb.BONUS_BAR)or(NF(GF,1)and 1)or nil
if not UF then
return nil
end
local VF=gb.grownKinds()>=gb.GROWN_MIN
