local ZF=JF.collection:get_unit_by_uuid(YF.uuid)or YF
local _F=(mb.unitDrop(ZF,MF))
if _F>0 and N.Units[ZF.unit_id]and V.rows(ZF.unit_id)and not V.hidden(ZF.unit_id)then
local aG,bG=pcall(N.USC.calculate_level,ZF.unit_id,tonumber(ZF.xp)or 0)
if V.isFarm(ZF.unit_id)or not VF or(aG and(tonumber(bG)or 0)>=gb.GROWN_LEVEL)then
local cG,dG=pcall(V.score,ZF,FF.mod)
dG=(cG and tonumber(dG)or 0)*V.eventMul(ZF,FF.ld)
if not WF[ZF.unit_id]or dG>WF[ZF.unit_id].sc then
WF[ZF.unit_id]={u=ZF,d=_F,sc=dG}
end
end
end
end
local eG={}
for fG,gG in pairs(WF)do
table.insert(eG,gG)
end
table.sort(eG,function(hG,iG)
if hG.d~=iG.d then
return hG.d>iG.d
end
return hG.sc>iG.sc
end)
if#eG==0 then
return nil
end
local jG,kG=table.clone(GF),{}
local lG=mb.teamDrop(jG,MF)
local mG=gb.realShares(FF.key,5)
local function nG(oG)
local pG,qG={},0
pcall(gb.run,FF,gb.teamFrom(oG,FF.map),{hpMul=1,dealt=pG})
task.wait()
for rG,sG in pairs(pG)do
qG=qG+(tonumber(sG)or 0)
end
local tG={}
for uG,vG in ipairs(oG)do
tG[vG.unit_id]=tonumber(mG[vG.unit_id])or(((tonumber(pG[V.name(vG.unit_id)])or 0)+(tonumber(pG[FOe[2911]..tostring(vG.unit_id)])or 0))/math.max(1,qG))
end
return tG
end
local wG=nG(jG)
for xG=1,mb.BONUS_SWAPS do
if mb.teamDrop(jG,MF)>=1 or U.now()-IF>HF then
break
end
local yG=false
for zG,AG in ipairs(eG)do
if U.now()-IF>HF then
break
end
local BG=false
for CG,EG in ipairs(jG)do
if EG.uuid==AG.u.uuid or V.sameGroup(EG.unit_id,AG.u.unit_id)then
BG=true
break
end
end
if not BG then
local FG={}
for GG,HG in ipairs(jG)do
if(mb.unitDrop(HG,MF))<AG.d then
table.insert(FG,{i=GG,sc=(tonumber(wG[HG.unit_id])or 0)+((V.isFarm(HG.unit_id)or V.allyBuff(HG.unit_id))and 1e300 or 0)})
end
end
table.sort(FG,function(IG,JG)
return IG.sc<JG.sc
end)
for KG=1,math.min(2,#FG)do
local LG=table.clone(jG)
local MG=LG[FG[KG].i]
LG[FG[KG].i]=AG.u
if mb.teamDrop(LG,MF)>mb.teamDrop(jG,MF)+1e-6 and NF(LG,UF)then
table.insert(kG,string.format(FOe[2912],V.name(AG.u.unit_id),V.name(MG.unit_id)))
jG,yG=LG,true
wG=nG(jG)
break
end
end
end
if yG then
break
end
end
if not yG then
break
end
end
if#kG==0 then
return nil
end
return jG,string.format(FOe[2913],table.concat(kG,FOe[2449]),math.floor(mb.teamDrop(jG,MF)*100+0.5),math.floor(lG*100+0.5),UF)
end
