function W.icWinP(tS)
local uS=tS.rec or W.rec(tS.key)
local vS=W.icLost(tS.room)
local wS=vS and vS.n or 0
local xS=((tonumber(uS.wins)or 0)+(tS.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(uS.runs)or 0)+2)
local yS=W.sim(tS)
