function ab.defOwned()
local hdb=N.session()
local idb=hdb and hdb.inventory and hdb.inventory.inventory_profile_data and hdb.inventory.inventory_profile_data.unique_items
local jdb,kdb={},{}
for ldb,mdb in pairs(type(idb)==FOe[2325]and idb or{})do
local ndb=type(mdb)==FOe[2325]and N.Items[mdb.item_id]
if ndb and ndb.item_group==FOe[1085]then
local odb=type(mdb._unique_item_data)==FOe[2325]and mdb._unique_item_data._unique_defense_data or{}
table.insert(jdb,{uuid=mdb.uuid,item_id=mdb.item_id,g=tonumber(odb.g)or 0,d=tonumber(odb.d),equipped=tonumber(odb._e)~=nil})
kdb[mdb.item_id]=(kdb[mdb.item_id]or 0)+1
end
end
return jdb,kdb
end
function ab.defBuyPick(pdb,qdb,rdb,sdb,tdb,udb,vdb)
local wdb=math.max(0,qdb-math.max(0,tonumber(rdb)or 0))
if tdb>=udb then
return nil
end
local xdb
for ydb,zdb in ipairs(pdb or{})do
local Adb=type(zdb)==FOe[2325]and ab.DEF_WANT[zdb.item_id]
local Bdb=type(zdb)==FOe[2325]and tonumber(zdb.price)or nil
if Adb and Bdb and Bdb<=wdb then
local Cdb=sdb[zdb.item_id]or 0
if tdb<vdb or Cdb==0 then
if not xdb or Cdb<xdb.have or(Cdb==xdb.have and Adb<xdb.pr)then
xdb={index=ydb,item_id=zdb.item_id,price=Bdb,have=Cdb,pr=Adb}
end
end
end
end
return xdb
end
function ab.defEquipPlan(Ddb,Edb)
local Fdb,Gdb,Hdb=0,{},{}
for Idb,Jdb in ipairs(Ddb)do
if Jdb.equipped then
Fdb=Fdb+1
Gdb[Jdb.item_id]=true
elseif ab.DEF_WANT[Jdb.item_id]and(Jdb.d==nil or Jdb.d>0)then
table.insert(Hdb,Jdb)
end
end
local Kdb={}
while Fdb+ #Kdb<Edb and#Hdb>0 do
table.sort(Hdb,function(Ldb,Mdb)
local Ndb,Odb=Gdb[Ldb.item_id]and 1 or 0,Gdb[Mdb.item_id]and 1 or 0
if Ndb~=Odb then
return Ndb<Odb
end
if ab.DEF_WANT[Ldb.item_id]~=ab.DEF_WANT[Mdb.item_id]then
return ab.DEF_WANT[Ldb.item_id]<ab.DEF_WANT[Mdb.item_id]
end
return Ldb.g>Mdb.g
end)
local Pdb=table.remove(Hdb,1)
Gdb[Pdb.item_id]=true
table.insert(Kdb,Pdb)
end
return Kdb
end
