local qeb=tonumber(keb(neb.item_id,peb))or 0
if qeb>0 then
table.insert(leb,{uuid=neb.uuid,item_id=neb.item_id,cost=qeb})
end
end
end
table.sort(leb,function(reb,seb)
return reb.cost<seb.cost
end)
local teb,ueb,veb=math.max(0,ieb-math.max(0,tonumber(jeb)or 0)),{},0
for web,xeb in ipairs(leb)do
if xeb.cost<=teb then
teb=teb-xeb.cost
veb=veb+xeb.cost
table.insert(ueb,xeb)
end
end
return ueb,veb
end
