function kb.gainXp(Dgb,Egb)
local Fgb,Ggb=tonumber(Dgb.xp)or 0,kb.xpFor(Dgb.unit_id,kb.cap(Dgb))
local Hgb=math.max(0,Ggb-Fgb)
if Hgb<=0 or(Egb or 0)<=0 then
return 0,0
end
local Igb=math.min(Egb,Hgb)
