function kb.relicWorth(Kgb,Lgb)
local Mgb=Lgb._unique_item_data and Lgb._unique_item_data._unique_relic_data
if not Mgb then
return 0
end
local Ngb=N.Items[Lgb.item_id]or{}
local Ogb,Pgb=V.types(Kgb.unit_id)
if Ngb.main_damage_type and Ngb.main_damage_type~=FOe[3036]and Ngb.main_damage_type~=Pgb then
return 0
end
local Qgb,Rgb=0,0
for Sgb,Tgb in pairs(Mgb._core_damage_type_buffs or{})do
if Ogb[Tgb.damage_type]then
Qgb=Qgb+(tonumber(Tgb.mul)or 0)+(tonumber(Tgb.add_upg)or 0)*0.01+(tonumber(Tgb.pen)or 0)*0.001
Rgb=Rgb+(tonumber(Tgb.crit)or 0)
end
end
Qgb=Qgb+Rgb*0.5
local Ugb=V.rows(Kgb.unit_id)
local Vgb=Ugb and Ugb[Ugb.max]
local Wgb=(Vgb and tonumber(Vgb.cd)or 0)*V.mult(Kgb,FOe[2776])
for Xgb,Ygb in pairs(Mgb._unique_relic_effects or{})do
local Zgb=type(Ygb.params)==FOe[2325]and Ygb.params or{}
if Ygb.id==FOe[3442]then
local _gb=math.min(1,(tonumber(Zgb.extra_damage)or 0)*Wgb/math.max(1,tonumber(Zgb.time_interval)or 40))
local ahb=V.DRONES and V.DRONES[Kgb.unit_id]
if ahb and ahb.late and Wgb>0 then
local bhb=1/Wgb
_gb=_gb*bhb/(bhb+(tonumber(ahb.max)or 0)*(tonumber(ahb.late.dmg)or 0)*(tonumber(ahb.hits)or 1)/math.max(0.1,tonumber(ahb.late.cd)or 4))
end
Qgb=Qgb+_gb
elseif Ygb.id==FOe[3443]then
Qgb=Qgb+(tonumber(Zgb.dmg_buff)or 0)*0.25
elseif Ygb.id==FOe[3444]then
Qgb=Qgb+(tonumber(Zgb.dmg_buff)or 0)*Rgb
elseif Ygb.id==FOe[3445]then
if Ogb.magic then
Qgb=0
else
Qgb=Qgb+(tonumber(Zgb.dmg_buff)or 0)*0.3
end
elseif Ygb.id==FOe[3446]then
if Ogb.water_damage then
Qgb=Qgb+0.05
end
elseif Ygb.id==FOe[2477]then
local chb=tonumber(Zgb.duration_buff)or tonumber(type(Ygb.static_params)==FOe[2325]and Ygb.static_params.duration_buff)or 2
local dhb,ehb=pcall(V.attackInfo,Vgb and Vgb.atk,Vgb and Vgb.range)
local fhb,ghb=dhb and tonumber(ehb.burn)or 0,dhb and tonumber(ehb.dot)or 0
if fhb<=0 then
local hhb,ihb=pcall(pb.model,Kgb.unit_id,dhb and ehb or nil,Vgb)
