for phb,qhb in ipairs(V.equipped())do
local rhb=qhb.data and qhb.data.rarity
if not V.isFarm(qhb.id)and(rhb==FOe[2915]or rhb==FOe[2916]or rhb==FOe[3440]or rhb==FOe[3447])then
local shb=kb.share(qhb.id)
if not P.str.share[qhb.id]then
shb=math.min(shb,0.15)
end
local thb={}
for uhb,vhb in ipairs(lhb)do
local whb=kb.relicWorth(qhb.u,vhb)*shb*100
if whb>0.01 then
table.insert(thb,{it=vhb,w=whb})
end
end
table.sort(thb,function(xhb,yhb)
if xhb.w~=yhb.w then
return xhb.w>yhb.w
end
return xhb.it.uuid<yhb.it.uuid
end)
local zhb,Ahb={},{}
for Bhb,Chb in ipairs(thb)do
local Dhb=Ahb[Chb.it.item_id]or 0
if#zhb<6 and Dhb<((N.Items[Chb.it.item_id]or{}).unique_equip and 1 or 2)then
Ahb[Chb.it.item_id]=Dhb+1
table.insert(zhb,Chb)
end
end
if qhb.u._equipped_relic then
local Ehb=false
for Fhb,Ghb in ipairs(zhb)do
if Ghb.it.uuid==qhb.u._equipped_relic then
Ehb=true
end
end
local Hhb=not Ehb and jhb.inventory:get_item_by_uuid(qhb.u._equipped_relic)
if Hhb then
table.insert(zhb,{it=Hhb,w=kb.relicWorth(qhb.u,Hhb)*shb*100})
end
