Khb[Qhb.e.uuid]=nil
Nhb(Ohb+1,Phb)
for Rhb,Shb in ipairs(Qhb.opts)do
local Thb=(N.Items[Shb.it.item_id]or{}).unique_equip
if not Lhb[Shb.it.uuid]and not(Thb and Mhb[Shb.it.item_id])then
Lhb[Shb.it.uuid]=true
if Thb then
Mhb[Shb.it.item_id]=true
end
Khb[Qhb.e.uuid]=Shb.it.uuid
Nhb(Ohb+1,Phb+Shb.w+(Shb.it.uuid==Qhb.e.u._equipped_relic and 0.01 or 0))
Khb[Qhb.e.uuid]=nil
Lhb[Shb.it.uuid]=nil
if Thb then
Mhb[Shb.it.item_id]=nil
end
end
end
end
Nhb(1,0)
local Uhb,Vhb=0,{}
for Whb,Xhb in ipairs(ohb)do
local Yhb=Xhb.e.u._equipped_relic and jhb.inventory:get_item_by_uuid(Xhb.e.u._equipped_relic)
local Zhb=Yhb and kb.relicWorth(Xhb.e.u,Yhb)*Xhb.share*100 or 0
Uhb=Uhb+Zhb
local aib=Ihb[Xhb.e.uuid]and jhb.inventory:get_item_by_uuid(Ihb[Xhb.e.uuid])
local bib=aib and kb.relicWorth(Xhb.e.u,aib)*Xhb.share*100 or 0
table.insert(Vhb,string.format(FOe[3448],V.name(Xhb.e.id),Yhb and(N.Items[Yhb.item_id]or{}).name or FOe[2926],Zhb,aib and(N.Items[aib.item_id]or{}).name or FOe[2926],bib))
end
