local Njb=2.1564^(Kjb-1)*(40+10*Ljb)/Mjb
if Ijb.kind==FOe[2350]then
Njb=3*30*2.1564^(Kjb-1)/Mjb
end
local Ojb=Kjb>=9 and 0.3 or(Kjb>=7 and 0.5 or 1)
