ab.FUSE_RANK={Rare=1,Epic=2,Legendary=3}
function ab.xpFodder(cnb)
local dnb=N.session()
local enb=ab.FUSE_RANK[O.fuseXpRarity]or 2
local fnb={[cnb.uuid]=true,[O.evolveUnit]=true}
for gnb,hnb in ipairs(V.equipped())do
fnb[hnb.uuid]=true
end
for inb,jnb in ipairs(P.savedTeam or{})do
fnb[jnb]=true
end
for knb,lnb in ipairs(P.train and P.train.on and P.train.on.base or{})do
fnb[lnb]=true
end
local mnb={}
local function nnb(onb)
local pnb=onb and N.Units[onb.unit_id]
local qnb=pnb and pnb.evolve and(onb.shiny and pnb.evolve.shiny or pnb.evolve.normal)
for rnb,snb in pairs(type(qnb)==FOe[2325]and type(qnb.unit_requirement)==FOe[2325]and qnb.unit_requirement or{})do
if type(snb)==FOe[2325]and snb.unit_id then
mnb[snb.unit_id]=math.max(mnb[snb.unit_id]or 0,tonumber(snb.amount)or 1)
end
end
end
pcall(nnb,cnb)
pcall(function()
nnb(dnb.collection:get_unit_by_uuid(O.evolveUnit))
end)
local tnb,unb={},0
for vnb,wnb in pairs(dnb.profile_data.collection.owned_units)do
local xnb=N.Units[wnb.unit_id]
local ynb=xnb and ab.FUSE_RANK[xnb.rarity]
if ynb and ynb<=enb and not fnb[vnb]and(mnb[wnb.unit_id]or 0)>0 then
mnb[wnb.unit_id]=mnb[wnb.unit_id]-1
ynb=nil
end
if ynb and ynb<=enb and not fnb[vnb]then
local znb=dnb.collection:get_unit_by_uuid(vnb)or wnb
if not(wnb._locked or znb._locked)and not(wnb._equipped_relic or znb._equipped_relic)then
local Anb,Bnb=pcall(N.USC.calculate_xp_gain_from_fuse,cnb,{znb},dnb)
Bnb=Anb and tonumber(Bnb)or 0
if Bnb>0 then
table.insert(tnb,{uuid=vnb,id=wnb.unit_id,xp=Bnb,rarity=xnb.rarity})
unb=unb+Bnb
end
end
end
end
table.sort(tnb,function(Cnb,Dnb)
if Cnb.xp~=Dnb.xp then
return Cnb.xp<Dnb.xp
end
return Cnb.uuid<Dnb.uuid
end)
local Enb=math.max(0,kb.xpFor(cnb.unit_id,kb.cap(cnb))-(tonumber(cnb.xp)or 0))
local Fnb,Gnb={},0
for Hnb,Inb in ipairs(tnb)do
if Gnb>=Enb then
break
end
table.insert(Fnb,Inb)
Gnb=Gnb+Inb.xp
end
return Fnb,Gnb,Enb,unb
end
