local bsb=gb.run(Hrb,_rb,{hpMul=1,train=vrb.uuid})
local csb=(bsb.tk or 0)/math.max(0.5,bsb.t/60)
if(bsb.won or Orb)and(not Xrb or csb>math.max(Xrb.rate*1.5,Xrb.rate+1))then
