Erb.ownMin=Nrb.t/60
if not Xrb then
Erb.why=Orb and string.format(FOe[3642],Prb,Arb and FOe[3643]or FOe[3644])or Arb and FOe[3645]or FOe[3646]
else
Erb.out,Erb.tk,Erb.minutes=Xrb.out,Xrb.r.tk or 0,Xrb.r.t/60
Erb.uuids={}
for dsb,esb in ipairs(Xrb.trial)do
table.insert(Erb.uuids,esb.uuid)
end
Erb.slow=(Nrb.won and not Orb)and Erb.minutes/math.max(0.1,Erb.ownMin)or 1
if Erb.tk<=0 and next(P.train.real)==nil then
