F.log(1,FOe[3649],string.format(FOe[3650],urb.label,V.name(vrb.id),Erb.out and(FOe[3651]..V.name(Erb.out))or FOe[1244],Erb.ok and string.format(FOe[3652],math.floor((ib.perRun(urb.key,vrb.id)or 0)+0.5),vrb.what,Erb.minutes,Erb.ownMin)or tostring(Erb.why)))
