for Tmc,Umc in ipairs(tmc)do
if V.sameGroup(Umc.unit_id,Rmc.unit_id)then
Smc=true
end
end
if not Smc and(not Pmc or V.isFarm(Rmc.unit_id))then
local Vmc=table.clone(tmc)
table.insert(Vmc,Rmc)
local Wmc=gb.run(omc,gb.teamFrom(Vmc,omc.map),{hpMul=zmc})
local Xmc=gb.objective(Wmc)
if not Omc or Xmc>Omc then
Nmc,Omc,Mmc=Rmc,Xmc,Wmc
end
end
end
if not Nmc then
break
end
table.insert(tmc,Nmc)
end
if Gmc and Bmc(tmc)==0 then
local Ymc,Zmc
for _mc=1,#tmc do
for anc,bnc in ipairs(xmc(tmc[_mc])and{}or qmc)do
