for unc,vnc in ipairs(qmc.rest)do
if U.now()-tnc>5 then
break
end
local wnc=false
for xnc,ync in ipairs(tmc)do
if V.sameGroup(ync.unit_id,vnc.unit_id)then
wnc=true
end
end
if not wnc then
local znc=table.clone(tmc)
znc[mnc]=vnc
table.insert(snc,{u=vnc,o=gb.objective(gb.run(omc,gb.teamFrom(znc,omc.map),{hpMul=zmc}))})
end
end
table.sort(snc,function(Anc,Bnc)
