end)
qmc=table.clone(qmc)
for Cnc=1,math.min(4,#snc)do
table.insert(qmc,1,snc[Cnc].u)
end
smc=smc+(U.now()-tnc)
end
end
for Dnc=1,2 do
local Enc=false
