function jb.sim(zvc,Avc,Bvc)
if not O.sim or type(zvc.r._l)~=FOe[2325]then
return nil
end
local Cvc=tostring(zvc.r._r or(zvc.d..FOe[2478]..zvc.choice))..(Avc and(FOe[2655]..tostring(Avc))or FOe[1244])..(Bvc and FOe[4439]or FOe[1244])
local Dvc=jb.data()
local Evc=jb.fx(Dvc,jb.roomCurse(zvc.r),Avc)
local Fvc=W.teamSig()..FOe[2338]..jb.fxText(Evc)..(O.killZone~=false and FOe[4440]or FOe[1244])..(bb.forcedWay()and(FOe[2338]..tostring(O.placeMode))or FOe[1244])
local Gvc=P.dg.sim[Cvc]
if Gvc and Gvc.sig==Fvc then
return not Gvc.none and Gvc or nil
end
local Hvc={}
for Ivc,Jvc in ipairs(V.equipped())do
table.insert(Hvc,Jvc.u)
end
if#Hvc==0 then
return nil
end
local Kvc=gb.applyFx(gb.info(gb.slim(zvc.r._l),FOe[3096],nil,jb.mod(zvc.r._l)),Evc)
jb.applyK(Kvc,zvc.r._r)
if Bvc then
Kvc.zone=false
end
local Lvc=gb.wave(Kvc,1,true)
if#Lvc==0 then
Gvc={none=true,sig=Fvc,at=os.time()}
else
local Mvc=gb.evaluate(Kvc,gb.teamFrom(Hvc,Kvc.map))
Gvc={p=Mvc.p,wave=Mvc.wave,won=Mvc.won,total=Kvc.total,margin=Mvc.margin,sig=Fvc,at=os.time(),zone=Kvc.zone~=false or nil}
end
P.dg.sim[Cvc]=Gvc
if U.count(P.dg.sim)>60 then
local Nvc,Ovc
for Pvc,Qvc in pairs(P.dg.sim)do
if not Ovc or(Qvc.at or 0)<Ovc then
Nvc,Ovc=Pvc,Qvc.at or 0
end
end
P.dg.sim[Nvc]=nil
end
F.saveSoon()
return not Gvc.none and Gvc or nil
end
function jb.winP(Rvc)
local Svc=tostring(math.min(4,math.max(1,math.ceil(Rvc.d/5))))
local Tvc=P.dg.depth[Svc]or{runs=0,wins=0}
local Uvc=U.clamp(0.95-0.015*Rvc.d,0.5,0.95)
local Vvc=((tonumber(Tvc.wins)or 0)+Uvc*2)/((tonumber(Tvc.runs)or 0)+2)
local Wvc,Xvc=pcall(jb.sim,Rvc)
if Wvc and Xvc and Xvc.p then
local Yvc,Zvc=pcall(gb.styleP,Xvc,Xvc.zone==false and FOe[4272]or(Xvc.zone and FOe[4206]or nil))
Vvc=(Vvc*2+(Yvc and Zvc or Xvc.p))/3
end
return Vvc,Wvc and Xvc or nil
end
function jb.hopeless(_vc)
return _vc~=nil and _vc.won==false and(tonumber(_vc.p)or 1)<=0.05
