end
function jb.curseOk(jwc,kwc,lwc,mwc,nwc)
local owc=tostring((jb.item(jwc)or{}).name or jwc)
local pwc,qwc,rwc=jb.curseBar(kwc,lwc)
if pwc>0.2 and jb.blindCurse(kwc,jwc)then
return false,string.format(FOe[4444],owc,rwc)
end
local function swc(twc)
return twc==nil or(tonumber(twc.p)or 1)>=pwc
end
if mwc then
local uwc,vwc=pcall(jb.sim,mwc,nil,true)
if uwc and not swc(vwc)then
return false,string.format(FOe[4445],owc,(qwc:gsub(FOe[4038],FOe[4446])),tostring(vwc.margin or FOe[2576]))
end
end
if#nwc==0 then
return true
end
local wwc
for xwc,ywc in ipairs(nwc)do
local zwc,Awc=pcall(jb.sim,ywc,jwc,true)
if not zwc or swc(Awc)then
return true
end
if not wwc or(tonumber(Awc.p)or 0)>(tonumber(wwc.p)or 0)then
wwc=Awc
end
end
return false,string.format(FOe[4447],owc,qwc,tostring(wwc and wwc.margin or FOe[2576]))
end
function jb.curseGate(Bwc,Cwc)
