end
function jb.payValue()
local Ewc,Fwc=0,0
for Gwc,Hwc in ipairs(P.dg.pay or{})do
if type(Hwc.items)==FOe[2325]then
local Iwc=tonumber(Hwc.gems)or 0
for Jwc,Kwc in pairs(Hwc.items)do
if(tonumber(Kwc)or 0)>0 then
Iwc=Iwc+W.itemValue(Jwc,Kwc)
end
end
Ewc,Fwc=Ewc+Iwc,Fwc+1
end
end
if Fwc<5 then
return nil
end
return Ewc/Fwc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local Lwc=type(P.dg)==FOe[2325]and type(P.dg.lossCalls)==FOe[2325]and P.dg.lossCalls or{}
return U.clamp(((tonumber(Lwc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(Lwc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(Mwc)
local Nwc,Owc=jb.curses(Mwc),jb.lives(Mwc)
local Pwc=jb.res(Mwc)
local Qwc=jb.rooms(Mwc)
local Rwc={}
for Swc,Twc in ipairs(Qwc)do
table.insert(Rwc,tostring(Twc.r._r))
end
local Uwc=table.concat(Rwc,FOe[3032])..string.format(FOe[4448],Owc,Pwc,Nwc,W.teamSig())
if jb._pick and jb._pick.sig==Uwc then
return jb._pick.x
end
local Vwc,Wwc,Xwc,Ywc
for Zwc,_wc in ipairs(Qwc)do
local axc=jb.roomValue(_wc,Pwc)
local bxc,cxc
for dxc,exc in ipairs(jb.after(Mwc,_wc.choice))do
local fxc=jb.roomValue(exc,Pwc)
if not bxc or fxc>bxc then
bxc,cxc=fxc,exc
end
end
local gxc,hxc=jb.winP(_wc)
local ixc=hxc~=nil and hxc.won==false
local jxc=Owc>=3 and 1 or(Owc==2 and 2 or 6)
local kxc=1-(1-gxc)^math.max(1,Owc)
_wc.oldScore=kxc*(axc+0.6*(bxc or 0))-(1-gxc)*jxc
if ixc then
gxc=math.min(gxc,jb.lossWin())
kxc=gxc
jxc=jxc*2
end
_wc.p,_wc.sim,_wc.value,_wc.nextValue,_wc.nextRoom,_wc.simLost=gxc,hxc,axc,bxc or 0,cxc,ixc or nil
_wc.score=kxc*(axc+0.6*(bxc or 0))-(1-gxc)*jxc
local lxc,mxc,nxc=pcall(jb.curseGate,_wc,Mwc)
if lxc and not mxc then
_wc.blocked=nxc
end
if not _wc.blocked then
if not Vwc or _wc.score>Vwc.score then
Vwc=_wc
end
if ixc then
if not Ywc or _wc.score>Ywc.score then
Ywc=_wc
end
elseif not Xwc or _wc.score>Xwc.score then
Xwc=_wc
end
end
if not Wwc or _wc.score>Wwc.score then
Wwc=_wc
end
end
if Vwc and Vwc.simLost and Xwc then
F.log(1,FOe[4449],string.format(FOe[4450],jb.roomName(Vwc),tostring(Vwc.sim and Vwc.sim.margin or FOe[2576]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Xwc)))
elseif Vwc and Ywc and Ywc~=Vwc and Ywc.oldScore>Vwc.score then
F.log(1,FOe[4449],string.format(FOe[4451],jb.roomName(Ywc),tostring(Ywc.sim and Ywc.sim.margin or FOe[2576]),jb.roomName(Vwc)))
end
Vwc=Vwc or Wwc
jb._pick={sig=Uwc,x=Vwc,rooms=Qwc}
return Vwc
end
