table.insert(Pxc,{key=Qxc,id=Sxc,cost=Txc or tonumber(jb.item(Sxc).cost)or 0,bought=type(Rxc)==FOe[2325]and(Rxc.bought or Rxc.sold or Rxc.purchased)or nil})
end
end
if#Pxc==0 and not Oxc then
for Uxc,Vxc in pairs(Nxc)do
