function jb.buy(Wxc)
local Xxc=jb.res(jb.data())
local Yxc={}
if P.dg.buyArg==FOe[2718]then
Yxc={Wxc.id,Wxc.key}
else
Yxc={Wxc.key,Wxc.id}
end
if Yxc[1]==Yxc[2]then
Yxc[2]=nil
end
