local ayc,byc=F.request(FOe[4459],FOe[4064],_xc)
local cyc=U.now()
while U.now()-cyc<3 and jb.res(jb.data())>=Xxc do
task.wait(0.25)
end
if jb.res(jb.data())<Xxc then
P.dg.buyArg=(_xc==Wxc.id and Wxc.id~=Wxc.key)and FOe[2718]or FOe[4460]
return true
