jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(iyc,jyc)
local kyc=jb.cleared(iyc)
local lyc=jb.res(iyc)
local myc=1+0.1*(jb.items(iyc)._curse_shop or 0)
local nyc=jb.shopAhead(iyc)and math.ceil(jb.LUCK_RESERVE*myc)or 0
local oyc={}
local pyc,qyc={},0
for ryc,syc in ipairs(jb.offers(jyc and jyc.data))do
syc.cost=math.ceil(syc.cost*myc)
table.insert(pyc,tostring(jb.item(syc.id).name or syc.id))
if not syc.bought and not jb.isCurse(syc.id)then
syc.luck=tonumber(jb.item(syc.id).luck_increase)~=nil
syc.v=jb.itemValue(syc.id,iyc)
if not syc.luck and syc.v/math.max(1,syc.cost)<jb.MIN_WORTH then
qyc=qyc+1
elseif syc.v>0 and(syc.luck or kyc>=10 or syc.v/math.max(1,syc.cost)>=jb.TOP_WORTH)then
table.insert(oyc,syc)
end
end
end
table.sort(oyc,function(tyc,uyc)
if tyc.luck~=uyc.luck then
return tyc.luck
end
return tyc.v/math.max(1,tyc.cost)>uyc.v/math.max(1,uyc.cost)
end)
local vyc,wyc,xyc={},0,0
for yyc,zyc in ipairs(oyc)do
if zyc.cost<=lyc-(zyc.luck and 0 or nyc)then
if jb.buy(zyc)then
lyc=jb.res(jb.data())
table.insert(vyc,string.format(FOe[4461],tostring(jb.item(zyc.id).name or zyc.id),zyc.cost))
end
elseif zyc.cost<=lyc then
xyc=xyc+1
else
wyc=wyc+1
