function bb.buildPath()
bb.samples={}
local MEc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not MEc then
return
end
for NEc,OEc in pairs(MEc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[NEc.Name])then
local PEc={}
for QEc,REc in ipairs(OEc.points or{})do
table.insert(PEc,REc.part.Position)
end
local SEc=0
for TEc=2,#PEc do
SEc=SEc+(PEc[TEc]-PEc[TEc-1]).Magnitude
end
local UEc=0
for VEc=2,#PEc do
local WEc,XEc=PEc[VEc-1],PEc[VEc]
local YEc=(XEc-WEc).Magnitude
local ZEc=math.max(1,math.floor(YEc/2))
for _Ec=0,ZEc-1 do
local aFc=WEc:Lerp(XEc,_Ec/ZEc)
table.insert(bb.samples,{pos=aFc,prog=(UEc+YEc*_Ec/ZEc)/math.max(1,SEc),lane=NEc.Name})
end
UEc=UEc+YEc
end
if PEc[#PEc]then
table.insert(bb.samples,{pos=PEc[#PEc],prog=1,lane=NEc.Name})
end
end
end
pcall(bb.readHidden,MEc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local bFc=tonumber(bb.ld and bb.ld._portal_lanes)
local cFc=gb.laneList(bb.samples)
if bFc and bFc>=1 and cFc and#cFc>bFc then
bb.laneWant=bFc
end
bb.laneTotal=cFc and#cFc or 1
bb.countLanes()
end
function bb.readHidden(dFc)
local eFc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(eFc)~=FOe[2325]or not next(eFc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local fFc
for gFc,hFc in pairs(dFc)do
if eFc[gFc.Name]and type(hFc.points)==FOe[2325]and#hFc.points>=2 then
local iFc={}
for jFc,kFc in ipairs(hFc.points)do
iFc[jFc]=U.flat(kFc.part.Position)
end
local lFc={}
for mFc,nFc in ipairs(bb.samples)do
local oFc=tostring(nFc.lane)
lFc[oFc]=lFc[oFc]or{}
table.insert(lFc[oFc],nFc)
end
local pFc,qFc
for rFc,sFc in pairs(lFc)do
local tFc=0
for uFc=1,#iFc,math.max(1,math.floor(#iFc/20))do
local vFc=math.huge
for wFc,xFc in ipairs(sFc)do
local yFc=(U.flat(xFc.pos)-iFc[uFc]).Magnitude
if yFc<vFc then
vFc=yFc
end
end
tFc=tFc+vFc
end
if not qFc or tFc<qFc then
pFc,qFc=rFc,tFc
end
end
local zFc,AFc,BFc,CFc,DFc,EFc={},nil,nil,nil,0,0
for FFc,GFc in ipairs(iFc)do
local HFc,IFc=nil,math.huge
for JFc,KFc in ipairs(lFc[pFc])do
local LFc=(U.flat(KFc.pos)-GFc).Magnitude
if LFc<IFc then
IFc,HFc=LFc,KFc.prog
end
end
EFc=math.max(EFc,IFc)
if BFc then
local MFc=HFc-BFc
local NFc=(MFc>0.002 and 1)or(MFc< -0.002 and-1)or CFc
if CFc and NFc and NFc~=CFc then
table.insert(zFc,math.floor(BFc*1000+0.5)/1000)
end
CFc,DFc=NFc or CFc,DFc+math.abs(MFc)
else
AFc=HFc
end
BFc=HFc
if FFc%50==0 then
task.wait()
end
end
if BFc and EFc<=8 then
table.insert(zFc,math.floor(BFc*1000+0.5)/1000)
fFc=fFc or{}
fFc[gFc.Name]={from=math.floor((AFc or 0)*1000+0.5)/1000,len=math.floor(DFc*1000+0.5)/1000,turns=zFc,road=pFc}
end
end
end
if not fFc then
return
end
local OFc=bb.ld.map
P.maps[OFc]=P.maps[OFc]or{}
local PFc=P.maps[OFc].hidden
P.maps[OFc].hidden=fFc
if type(PFc)~=FOe[2325]then
for QFc,RFc in pairs(fFc)do
F.log(1,FOe[3013],string.format(FOe[4585],QFc,RFc.len,tostring(RFc.road),math.floor((#RFc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local SFc,TFc,UFc={},0,0
for VFc,WFc in ipairs(bb.samples)do
local XFc=tostring(WFc.lane)
