local wJc=uJc and math.max(uJc.Size.X,uJc.Size.Z)/2 or 1.5
if(qJc-U.flat(vJc)).Magnitude<pJc+wJc then
return nil
end
end
if not mJc then
for xJc,yJc in ipairs(bb.blockers())do
if(qJc-yJc.p).Magnitude<pJc+yJc.r then
return nil
end
end
end
return oJc
end
function bb.buildCandidates()
