local DJc=U.flat(CJc.pos-BJc.pos)
if DJc.Magnitude<0.01 then
DJc=Vector3 .new(1,0,0)
end
DJc=DJc.Unit
local EJc=Vector3 .new(-DJc.Z,0,DJc.X)
for FJc,GJc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for HJc,IJc in ipairs({1,-1})do
