end
end
local RJc,SJc=0,0
if#NJc>0 then
for TJc,UJc in ipairs(bb.samples)do
if UJc.prog>SJc then
local VJc=U.flat(UJc.pos)
for WJc,XJc in ipairs(NJc)do
if(VJc-XJc.p).Magnitude<=XJc.r then
