local YJc,ZJc={},bb.laneCount
if ZJc and ZJc.n>=2 and#NJc>0 then
local _Jc={}
for aKc,bKc in ipairs(bb.samples)do
local cKc=U.flat(bKc.pos)
for dKc,eKc in ipairs(NJc)do
if(cKc-eKc.p).Magnitude<=eKc.r then
local fKc=tostring(bKc.lane)
_Jc[fKc]=(_Jc[fKc]or 0)+1
if bKc.prog>(YJc[fKc]or 0)then
YJc[fKc]=bKc.prog
end
break
end
end
end
local gKc,hKc={},0
for iKc,jKc in pairs(ZJc.by)do
gKc[iKc]=(_Jc[iKc]or 0)/math.max(1,jKc)
hKc=math.max(hKc,gKc[iKc])
