for w0c,x0c in ipairs(V_c)do
local y0c=os.clock()
local z0c=gb.runRaw(Q_c,R_c,{hpMul=x0c,layout=j0c(s0c),bg=true})
t0c,u0c,v0c=t0c+gb.objective(z0c),u0c+(tonumber(z0c.kills)or 0),v0c+(tonumber(z0c.wave)or 0)
