end
local _0c={L0c}
for a1c,b1c in ipairs(N_c.attackers)do
local c1c={}
for d1c,e1c in ipairs(_0c)do
table.insert(c1c,e1c)
for f1c,g1c in ipairs(Y_c[b1c.id]or{})do
if g1c~=e1c.spots[b1c.id]and not F0c(e1c.spots,b1c.id,g1c)then
local h1c=A0c(e1c.spots)
h1c[b1c.id]=g1c
local i1c,j1c,k1c=r0c(h1c)
