while P_c()and#p1c>0 do
local s1c=A0c(L0c.spots)
for t1c=1,math.min(2,#p1c)do
local u1c=p1c[math.random(#p1c)]
local v1c=Y_c[u1c]
local w1c=v1c[math.random(#v1c)]
if not F0c(s1c,u1c,w1c)then
s1c[u1c]=w1c
end
end
local x1c,y1c,z1c=r0c(s1c)
if not x1c then
break
end
X0c({spots=s1c,s=x1c,kills=y1c,wave=z1c})
