bb.STUDY_INF_WAIT=240
function bb.validOpen(A1c,B1c)
local C1c=N.PC.raycast(A1c+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not C1c then
return nil
end
if not N.PC.is_valid_raycast_hit(C1c.Instance,B1c)then
return nil
end
local D1c=C1c.Position
if bb.blockedSpot(D1c)then
return nil
end
local E1c=(tonumber(B1c.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(E1c*2,2.5,E1c*2)
bb.probe.CFrame=CFrame.new(D1c+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return D1c
end
