if not V.isFarm(K1c.id)and not V.allyBuff(K1c.id)and K1c.uuid~=bb.trainee and V.rows(K1c.id)then
local L1c,M1c=pcall(V.score,K1c.u,bb.mod)
table.insert(I1c,{e=K1c,id=K1c.id,sc=L1c and M1c or 0})
end
end
if#I1c==0 then
return
end
table.sort(I1c,function(N1c,O1c)
return N1c.sc>O1c.sc
end)
local function P1c()
local Q1c,R1c={},0
for S1c,T1c in ipairs(I1c)do
for U1c,V1c in ipairs(bb.mine or{})do
local W1c=V1c:FindFirstChild(FOe[2397])
local X1c=W1c and W1c:FindFirstChild(FOe[2717])
if X1c and X1c.Value==T1c.e.uuid and W1c:FindFirstChild(FOe[2718])and W1c.id.Value==T1c.id then
Q1c[T1c.id]=V1c:GetPivot().Position
R1c=R1c+1
break
end
end
end
return Q1c,R1c
end
local Y1c=U.now()
