function bb.bookSave(x2c,y2c,z2c,A2c)
P.mapBook=type(P.mapBook)==FOe[2325]and P.mapBook or{}
local B2c={}
for C2c,D2c in pairs(z2c.spots or{})do
B2c[C2c]={math.floor(D2c.X*10+0.5)/10,math.floor(D2c.Y*10+0.5)/10,math.floor(D2c.Z*10+0.5)/10}
