bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(f3c,g3c)
local h3c=bb.bookKey(f3c)
P.layoutRec=type(P.layoutRec)==FOe[2325]and P.layoutRec or{}
local i3c=P.layoutRec[h3c]
if type(i3c)~=FOe[2325]then
if not g3c then
