end
i3c={at=os.time()}
P.layoutRec[h3c]=i3c
if U.count(P.layoutRec)>80 then
local j3c,k3c
for l3c,m3c in pairs(P.layoutRec)do
local n3c=type(m3c)==FOe[2325]and tonumber(m3c.at)or 0
if not k3c or n3c<k3c then
j3c,k3c=l3c,n3c
end
end
P.layoutRec[j3c]=nil
end
