return i3c
end
function bb.layoutAdd(o3c,p3c,q3c,r3c,s3c)
o3c.runs,o3c.wins=(tonumber(o3c.runs)or 0)+1,(tonumber(o3c.wins)or 0)+(p3c and 1 or 0)
o3c.sec,o3c.wave=type(o3c.sec)==FOe[2325]and o3c.sec or{},type(o3c.wave)==FOe[2325]and o3c.wave or{}
if p3c and tonumber(q3c)then
table.insert(o3c.sec,math.floor(q3c+0.5))
end
table.insert(o3c.wave,tonumber(r3c)or 0)
if tonumber(s3c)then
o3c.kills=type(o3c.kills)==FOe[2325]and o3c.kills or{}
table.insert(o3c.kills,math.floor(tonumber(s3c)))
while#o3c.kills>bb.LAYOUT_KEEP do
table.remove(o3c.kills,1)
end
end
while#o3c.sec>bb.LAYOUT_KEEP do
table.remove(o3c.sec,1)
end
while#o3c.wave>bb.LAYOUT_KEEP do
table.remove(o3c.wave,1)
end
end
function bb.layoutJudge(t3c,u3c,v3c,w3c,x3c)
x3c=x3c or FOe[4787]
local y3c,z3c=tonumber(t3c and t3c.runs)or 0,tonumber(u3c and u3c.runs)or 0
if y3c<1 or z3c<bb.LAYOUT_CONTROL then
