if not bcd or ecd>bcd then
acd,bcd=dcd,ecd
end
end
if acd then
local fcd,gcd={},{}
for hcd=1,gb.BINS do
fcd[hcd]=FOe[4424]
end
for icd,jcd in ipairs(Zbd or{})do
gcd[jcd]={}
for kcd=1,gb.BINS do
gcd[jcd][kcd]=FOe[4424]
end
end
local lcd=U.flat(acd)
for mcd,ncd in ipairs(bb.samples)do
