if type(Rgd)~=FOe[2325]or Rgd.push==nil or Rgd.push~=Qgd or(tonumber(bb.pressure)or 0)>=gb.REINC_PUSH then
return 1
end
return gb.REINC_BOOST
end
function bb.reincOn()
local Sgd=bb.reinc
if type(Sgd)==FOe[2325]and Sgd.id and Sgd.study then
return not(bb.random or bb.noBuy)
end
if type(Sgd)~=FOe[2325]or not Sgd.id or O.phoenixSell==false or bb.random or bb.noBuy or not gb.reincLong(bb.info)then
return false
end
if bb.trialId and bb.trialId~=Sgd.id then
return false
end
return Sgd.ok~=false
end
