local Emd=Dmd*math.pi/6+Cmd
table.insert(ymd,Vector3 .new(wmd.p.X+math.cos(Emd)*wmd.r*Cmd,wmd.y,wmd.p.Z+math.sin(Emd)*wmd.r*Cmd))
end
end
