end
end
end
end
local Vmd={}
for Wmd,Xmd in ipairs(bb.cands or{})do
if Wmd%40==0 then
task.wait()
end
local Ymd=bb.valid(Xmd,vmd)
if Ymd then
table.insert(Vmd,{f=U.flat(Ymd),p=Ymd})
end
end
local Zmd,_md
local bnd=math.max(1,math.floor(#Vmd/150))
for cnd=1,#Vmd,bnd do
local dnd=Vmd[cnd].f
local fnd=true
for gnd,hnd in ipairs(Omd)do
if(hnd-dnd).Magnitude<=Nmd+2 then
fnd=false
break
end
end
if fnd then
local ind=0
for jnd,knd in ipairs(Vmd)do
if(knd.f-dnd).Magnitude<=Nmd*bb.GRIF_ROOM then
ind=ind+1
