end
local rnd=bb.grifNow
if not rnd or rnd.m~=qnd.m then
return
end
local snd={}
for tnd,und in ipairs(rnd.fodder)do
snd[und]=true
end
for vnd= #lnd,1,-1 do
if lnd[vnd].m and snd[lnd[vnd].m]then
table.remove(lnd,vnd)
end
end
qnd.more=false
if not bb.grifLong()then
if not qnd.lateSaid then
qnd.lateSaid=true
