end
local wnd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,wnd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return
end
local xnd=math.max(1,rnd.need-rnd.yen)
local ynd=(bb.info and tonumber(bb.info.waveSec))or 20
local znd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/ynd))
local And=math.max(0,xnd-mnd)/znd
local Bnd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+And/(6*ynd))
if Bnd<=0 then
return
end
local Cnd=string.format(FOe[4955],U.fmt(rnd.yen),U.fmt(rnd.need))
for Dnd,End in ipairs(rnd.fodder)do
local Fnd=End._stats
local Gnd=Fnd.id.Value
local Hnd=V.rows(Gnd)
local Ind=tonumber(Fnd.upgrade.Value)or 0
local Jnd=Hnd and Hnd[Ind+1]
if Jnd and Ind<Hnd.max and not((bb.upFail[End]or 0)>=3 and U.now()-(bb.upFailAt[End]or 0)<60)then
local Knd=1
pcall(function()
Knd=N.USC.calculate_upgrade_cost_multiplier(End,N.session())
end)
local Lnd=Jnd.cost*Knd
qnd.more=true
if rnd.yen<rnd.need then
table.insert(lnd,{grif=true,cost=Lnd,gain=Bnd*Lnd,m=End,what=string.format(FOe[4956],V.name(Gnd),Ind+1,Cnd)})
end
end
end
if rnd.yen>=rnd.need or bb.fieldCount()>=bb.FIELD_MAX or bb.placePaused()then
return
end
for Mnd,Nnd in ipairs(qnd.fodder)do
if#(ond[Nnd.uuid]or{})<V.cap(Nnd.u)and(bb.noSpot[Nnd.uuid]or 0)<3 then
local Ond=(tonumber(Nnd.data.cost)or 0)*nnd
qnd.more=true
table.insert(lnd,{place=true,grif=true,cost=Ond,gain=Bnd*Ond,e=setmetatable({_grif=true},{__index=Nnd}),what=string.format(FOe[4957],V.name(Nnd.id),Cnd)})
end
end
end
function bb.grifEggGain(Pnd,Qnd)
