local Snd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
if(bb.pressure or 0)>=math.min(O.dangerReach,Snd*0.9)*0.8 or(bb.depth and bb.depth.leak)then
return 0
end
local Tnd=(bb.info and tonumber(bb.info.waveSec))or 20
