if pod and(bb.grifS.done or bb.grifS.off)then
if bb.grifS.done then
return false
end
pod=false
end
if not bb.infinite and bb.total and bb.wave()>=bb.total-2 then
return false
end
local qod,rod=U.flat(lod:GetPivot().Position),tonumber(nod.range.Value)or 0
local sod,tod,uod,vod=0,{},0,{}
for wod,xod in ipairs(bb.mine or{})do
local yod=xod~=lod and xod:FindFirstChild(FOe[2397])
local zod=yod and yod:FindFirstChild(FOe[2718])and yod.id.Value
if zod and(U.flat(xod:GetPivot().Position)-qod).Magnitude<=rod then
if V.sacFodder(zod)then
sod=sod+1
local Aod=yod:FindFirstChild(FOe[4629])and tonumber(yod.total_spent.Value)or 0
uod=uod+Aod
vod[xod]=Aod
else
tod[V.name(zod)]=true
end
end
end
if next(tod)then
bb.sacSaid=bb.sacSaid or{}
if not bb.sacSaid[lod]then
bb.sacSaid[lod]=true
