local yrd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local zrd=mb.weatherStrength(mb.weatherNow())
local Ard=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or FOe[1248]
local Brd,Crd,Drd,Erd
local Frd={}
