end
if type(Hrd)==FOe[2325]and(Hrd.title or Hrd.name)then
bb.fhFactors[tostring(Hrd.title or Hrd.name):lower():gsub(FOe[5001],FOe[1244])]=Ird
end
local Nrd=type(Hrd)==FOe[2325]and mb.cardGems(Hrd,wrd)or 0
