if Ard==FOe[1246]and Ord and Rrd>0 then
Qrd=2e6+Rrd*1e4+Nrd
elseif Ard==FOe[2343]and Ord then
Qrd=1e6+mb.cardPearls(Hrd,wrd)*10+Nrd+Prd
elseif Ard==FOe[2905]then
Qrd=Prd*1e6+Nrd
