end
xsd,ysd=xsd+(tonumber(Bsd.pearls)or 0),ysd+(tonumber(Bsd.sec)or 0)
table.insert(zsd,tonumber(Bsd.wave)or 0)
end
if ysd<=0 then
return nil
end
table.sort(zsd)
local Csd=zsd[math.ceil(#zsd/2)]
local Dsd=xsd/ysd*60*(tonumber(O.pearlValue)or 0.35)
local Esd={string.format(FOe[5026],bb.HUNT_WEAK_RUNS,Csd,Dsd)}
local Fsd
for Gsd,Hsd in ipairs(W.lastScored or{})do
if Hsd.kind~=FOe[2348]and(tonumber(Hsd.score)or 0)>0 then
Fsd=Hsd
break
end
end
if Fsd then
table.insert(Esd,string.format(FOe[5027],tostring(Fsd.label),Fsd.score))
end
local Isd=0
for Jsd,Ksd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[Ksd]==false then
Isd=Isd+1
end
end
if W.onlyOn()then
table.insert(Esd,FOe[5028])
elseif Isd>=4 then
table.insert(Esd,string.format(FOe[5029],Isd))
