for mtd,ntd in ipairs(bb.mine or{})do
local otd=ntd._stats.id.Value
if not V.isFarm(otd)then
local ptd,qtd=pcall(bb.liveDps,ntd,otd)
qtd=ptd and qtd or 0
local rtd=V.types(otd)
ktd=ktd+qtd
if rtd[jtd]or rtd[jtd..FOe[2544]]then
ltd=ltd+qtd
end
end
end
local std=0
for ttd,utd in ipairs(bb.mine or{})do
if not V.isFarm(utd._stats.id.Value)then
std=std+1
end
end
local vtd=std/(std+4)
return vtd*(ktd>0 and ltd/ktd or 0.5)+(1-vtd)*0.5
end
function bb.resistOf(wtd)
