function bb.rogueEffect(Ctd)
local Dtd,Etd,Ftd=Ctd.type,tonumber(Ctd.amount)or 0,tostring(Ctd.stat or FOe[1244])
if Dtd==FOe[2887]then
return 1,math.abs(Etd)
end
if Dtd==FOe[4413]or Dtd==FOe[4418]or Dtd==FOe[4414]then
if Ftd==FOe[2775]then
return math.max(0.3,1+Etd),0
end
if Ftd==FOe[2593]then
return math.max(0.5,1+Etd/2),0
end
if Ftd:find(FOe[3145])then
return 1/math.max(0.3,1+Etd),0
end
return 1,0
end
if Dtd==FOe[5033]then
if Ftd==FOe[2775]then
return math.max(0.3,Etd),0
end
if Ftd==FOe[2593]then
return math.max(0.5,1+(Etd-1)/2),0
end
if Ftd:find(FOe[3145])then
return 1/math.max(0.3,Etd),0
end
return 1,0
end
if Dtd==FOe[4420]then
return 1+Etd/3,0
end
if Dtd==FOe[4426]then
return 1/math.max(0.3,1+Etd),0
end
if Dtd==FOe[5034]then
return math.max(0.2,1-bb.rogueShare(Ctd.damage_type)*(1-100/(100+Etd))),0
end
if Dtd==FOe[5035]then
return 1+bb.rogueShare(Ctd.damage_type)*Etd,0
end
if Dtd==FOe[5036]then
return math.max(0.5,1-Etd*0.5),0
end
if Dtd==FOe[5037]then
return math.max(0.5,1-Etd*0.2),0
end
if Dtd==FOe[5038]then
return 1+Etd*0.1,0
end
if Dtd==FOe[5039]then
return 1/math.max(0.3,1+Etd*0.5),0
end
if Dtd==FOe[5040]then
return math.max(0.5,1-Etd*0.1),0
end
if Dtd==FOe[4421]then
return 1/math.max(0.3,1+Etd),0
end
if Dtd==FOe[4427]then
return math.max(0.3,1-Etd*20),0
end
if Dtd==FOe[4428]then
return math.max(0.5,1-Etd*0.03),0
end
if Dtd==FOe[5041]then
return 0.95,0
end
if Dtd==FOe[4429]then
return math.max(0.5,1-Etd),0
end
if Dtd==FOe[5042]then
return 1+math.min(0.3,Etd/40000),0
end
if Dtd==FOe[4422]then
return 1/math.max(0.3,1+Etd/2),0
end
if Dtd==FOe[5043]then
return 0.8,0
end
if Dtd==FOe[5044]then
local Gtd=math.max(1,math.abs(Etd))*math.max(1,math.abs(tonumber(Ctd.tier)or 1))
return Ctd._type==FOe[5045]and 1.1^Gtd or 0.8^Gtd,0
end
return 1,0
end
