function bb.learn()
local Itd=bb.calRun and bb.calRun.potBy
if type(Itd)~=FOe[2325]then
return
end
pcall(bb.sampleHelpers,true)
local Jtd={}
for Ktd,Ltd in pairs(bb.ownDealt or{})do
if not V.isFarm(Ltd.id)then
Jtd[Ltd.id]=(Jtd[Ltd.id]or 0)+(tonumber(Ltd.v)or 0)
end
end
for Mtd,Ntd in pairs(bb.helperDealt or{})do
if Ntd.owner and V.SUMMONER[Ntd.owner]and not V.droneHelper(Ntd)then
Jtd[Ntd.owner]=(Jtd[Ntd.owner]or 0)+(tonumber(Ntd.v)or 0)
end
end
local Otd=type(bb.calRun.potExp)==FOe[2325]and bb.calRun.potExp or{}
local Ptd,Qtd=0,0
local Rtd={}
for Std,Ttd in pairs(Itd)do
if Ttd>0 then
Ptd,Qtd=Ptd+(Jtd[Std]or 0),Qtd+Ttd
local Utd=tonumber(Otd[Std])or Ttd
if Utd>0 then
table.insert(Rtd,{id=Std,r=(Jtd[Std]or 0)/Utd,w=Utd})
end
end
end
if Ptd<=0 or Qtd<=0 then
return
end
table.sort(Rtd,function(Vtd,Wtd)
return Vtd.r<Wtd.r
end)
local function Xtd(Ytd)
local Ztd,_td=0,0
for aud,bud in ipairs(Rtd)do
if bud.id~=Ytd then
Ztd=Ztd+bud.w
end
end
if Ztd<=0 then
return nil
end
for cud,dud in ipairs(Rtd)do
if dud.id~=Ytd then
_td=_td+dud.w
if _td>=Ztd/2 then
return dud.r
end
end
end
end
bb.lastEff={}
for eud,fud in pairs(Itd)do
local gud=Xtd(eud)
if fud>0 and fud/Qtd>0.02 and gud and gud>0 then
local hud=P.learn[eud]or{eff=1,n=0,v=6}
V.learnUp(eud,hud)
local iud=math.max(0.02,0.25*math.sqrt(30/(30+hud.n)))
local jud=U.clamp(((Jtd[eud]or 0)/fud)/gud,0.2,6)
bb.lastEff[eud]=math.floor(jud*1000+0.5)/1000
hud.eff=hud.eff+(jud-hud.eff)*iud
hud.n=hud.n+1
P.learn[eud]=hud
end
end
local kud=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if kud and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==FOe[2325]and P.mapLearn or{}
local lud=type(P.mapLearn[kud])==FOe[2325]and P.mapLearn[kud]or{}
for mud,nud in pairs(bb.lastEff)do
local oud=type(lud[mud])==FOe[2325]and lud[mud]or{eff=nud,n=0,v=6}
if(tonumber(oud.v)or 0)<4 then
oud.eff,oud.v=(tonumber(oud.eff)or nud)*V.secRescale(mud),4
end
if(tonumber(oud.v)or 0)<5 then
oud.eff,oud.v=(tonumber(oud.eff)or nud)*(V.sumRescale(mud)or 1),5
end
if(tonumber(oud.v)or 0)<6 then
oud.eff,oud.v=(tonumber(oud.eff)or nud)*(1-(V.SUMMONER[mud]and V.SUMMONER[mud].droneShare or 0)),6
end
local pud=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(oud.n)or 0))))
oud.eff=(tonumber(oud.n)or 0)==0 and nud or((tonumber(oud.eff)or nud)+(nud-(tonumber(oud.eff)or nud))*pud)
oud.n=(tonumber(oud.n)or 0)+1
lud[mud]=oud
end
lud._at=os.time()
P.mapLearn[kud]=lud
if U.count(P.mapLearn)>80 then
local qud,rud
for sud,tud in pairs(P.mapLearn)do
if not rud or(tonumber(tud._at)or 0)<rud then
qud,rud=sud,tonumber(tud._at)or 0
end
end
P.mapLearn[qud]=nil
end
end
end
function bb.randomTeam()
