bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(xAd,yAd)
local zAd=(yAd.t or 0)-(xAd.t or 0)
if zAd<bb.BASE_WIN-1 then
return false
end
local AAd=((tonumber(xAd.base)or 0)-(tonumber(yAd.base)or 0))/zAd
if AAd<=0 or(tonumber(yAd.base)or 0)<=0 then
return false
end
local BAd=yAd.base/AAd
local CAd,DAd=0,0
local EAd,FAd=xAd.foes or{},yAd.foes or{}
for GAd,HAd in pairs(FAd)do
if HAd.prog>=bb.BASE_END then
CAd=CAd+HAd.hp
local IAd=EAd[GAd]
if IAd then
DAd=DAd+math.max(0,IAd.hp-HAd.hp)
end
end
end
for JAd,KAd in pairs(EAd)do
if KAd.prog>=bb.BASE_END and not FAd[JAd]then
DAd=DAd+KAd.hp
end
end
if CAd<=0 then
return false
end
local LAd=DAd/zAd
local MAd=LAd>0 and CAd/LAd or math.huge
local NAd={baseTime=BAd,loss=AAd,atEnd=CAd,rate=LAd,killTime=MAd}
return BAd<bb.BASE_SOON and MAd>BAd*bb.BASE_MARGIN,NAd
end
