local uBd,vBd=U.flat(qBd:GetPivot().Position),tBd.Value
if(not mBd.fly or bb.canAir(qBd))and(uBd-oBd).Magnitude>vBd then
for wBd,xBd in ipairs(bb.samples or{})do
if xBd.prog>mBd.prog and(U.flat(xBd.pos)-uBd).Magnitude<=vBd then
nBd=nBd+1
