end
local ABd=workspace:FindFirstChild(FOe[5146])and workspace._BASES:FindFirstChild(FOe[4586])
local BBd=ABd and ABd:FindFirstChild(FOe[4844])and ABd.base:FindFirstChild(FOe[4845])
local CBd=BBd and BBd:FindFirstChildOfClass(FOe[2734])
if not CBd or CBd.Health<=0 then
