end
local DBd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local EBd=U.now()
bb.leakTrack=bb.leakTrack or{}
local FBd=bb.leakTrack
local GBd,HBd={},nil
for IBd,JBd in ipairs(bb.enemies or{})do
if JBd.m then
GBd[JBd.m]=true
local KBd,LBd=tonumber(JBd.hp)or 0,tonumber(JBd.prog)or 0
local MBd=FBd[JBd.m]
if not MBd then
FBd[JBd.m]={t=EBd,hp=KBd,prog=LBd}
else
if EBd-MBd.t>=bb.LEAK_WIN then
MBd.pace,MBd.net=(LBd-MBd.prog)/(EBd-MBd.t),(MBd.hp-KBd)/(EBd-MBd.t)
