local ZBd=YBd.id.Value
if not V.isFarm(ZBd)and not V.allyBuff(ZBd)and YBd:FindFirstChild(FOe[2593])then
local _Bd=tonumber(YBd.range.Value)or 0
local aCd=bb.coverMax[XBd]
if not(aCd and aCd.r==_Bd)then
local bCd,cCd=U.flat(XBd:GetPivot().Position),-1
for dCd,eCd in ipairs(bb.samples or{})do
if eCd.prog>cCd and(U.flat(eCd.pos)-bCd).Magnitude<=_Bd then
cCd=eCd.prog
end
end
aCd={r=_Bd,far=cCd}
bb.coverMax[XBd]=aCd
