if not qCd or qCd.m~=mCd.m then
qCd={m=mCd.m,id=lCd,name=tCd,wave=bb.wave(),t0=U.now(),max=sCd,low=1,assassin=jCd.assassin,beatAt=tonumber(jCd.beatAt)or 0.5,walk=jCd.walk}
