function bb.modPair(fPd,gPd)
if gPd<=0.02 or gPd>=1.2 then
return
end
local hPd=P.enemyMods[fPd]or{r={}}
P.enemyMods[fPd]=hPd
table.insert(hPd.r,gPd)
while#hPd.r>80 do
table.remove(hPd.r,1)
end
local iPd=gb.modRead(hPd)
local jPd=hPd.said and iPd and math.abs(iPd-hPd.said)<=hPd.said*0.1
if iPd and not jPd then
hPd.said=iPd
end
local kPd,lPd=fPd==FOe[4211]and FOe[5337]or(fPd==FOe[2884]and FOe[5338]or FOe[4212]),fPd==FOe[4211]and FOe[5339]or(fPd==FOe[4210]and FOe[5340]or FOe[5341])
if iPd and not jPd then
F.log(1,FOe[3013],string.format(FOe[5342],kPd,#hPd.r,iPd,lPd))
end
if iPd==false and not hPd.saidLoose then
hPd.saidLoose=true
local mPd=table.clone(hPd.r)
table.sort(mPd)
F.log(1,FOe[3013],string.format(FOe[5343],kPd,#mPd,mPd[1],mPd[#mPd]))
end
end
