for SPd,TPd in pairs(RPd and RPd.weak or{})do
QPd[string.format(FOe[5355],gb.typeWord(SPd),TPd)]=true
end
for UPd in pairs(RPd and RPd.res or{})do
QPd[FOe[4284]..gb.typeWord(UPd)]=true
end
for VPd in pairs(RPd and RPd.strong or{})do
QPd[FOe[4285]..gb.typeWord(VPd)]=true
end
for WPd,XPd in pairs(type(PPd)==FOe[2325]and type(PPd._levelmodifiers)==FOe[2325]and PPd._levelmodifiers or{})do
local YPd=type(XPd)==FOe[2325]and XPd.id or XPd
local ZPd=MPd[tostring(YPd)]
QPd[tostring(ZPd and ZPd.name or YPd)]=true
end
if type(PPd)==FOe[2325]and type(PPd._weather)==FOe[1230]and PPd._weather~=FOe[1244]then
local _Pd=NPd[PPd._weather]
QPd[FOe[5356]..tostring(_Pd and _Pd.name or PPd._weather)]=true
end
return QPd
end
local aQd,bQd=pcall(gb.levelFor,{key=bb.key,kind=bb.kind,level=bb.ld.id,diff=bb.ld._difficulty,room=tonumber(bb.ld._infinite_tower_floor),challenge=bb.ld._challenge})
